def check_occurences(tuples):
    """
    Counts the occurrences of tuples that occur similar times in the given tuples.

    Two tuples are considered "similar" if they differ only in the last element.
    For example, (1, 3) and (1, 6) are similar, while (1, 3) and (2, 3) are not.

    Args:
        tuples (list of tuples): A list of tuples to analyze.

    Returns:
        dict: A dictionary mapping tuples to their occurrence counts.
    """
    # Dictionary to store counts
    counts = {}

    # Group tuples by their first two elements
    groups = {}
    for t in tuples:
        # Create a key based on the first two elements
        key = (t[0], t[1])
        if key not in groups:
            groups[key] = []
        groups[key].append(t)

    # Count occurrences for each group
    for key, group in groups.items():
        if len(group) > 1:
            # Count occurrences of each tuple in the group
            for t in group:
                if t in counts:
                    counts[t] += 1
                else:
                    counts[t] = 1
        else:
            # Only one tuple in the group
            if key in counts:
                counts[key] += 1
            else:
                counts[key] = 1

    return counts
